// 1. Input Validation and Initialization
if (wo_input.enable != 1) {
    wo_state.mode = WO_OFF;
    wo_state.history_initialized = 0;
    wo_state.clean = 0;
    wo_state.elapsed = 0;
    wo_state.recovery_count = 0;
    for (int i = 0; i < 4; ++i) wo_state.previous_speed_rad_s[i] = 0.0;
    wo_state.previous_torque.x = 0.0;
    wo_state.previous_torque.y = 0.0;
    wo_state.previous_torque.z = 0.0;

    wo_output.mode = WO_OFF;
    wo_output.clean = 0;
    wo_output.elapsed = 0;
    wo_output.recovery_count = 0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (int i = 0; i < 4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum.x = 0.0;
    wo_output.momentum.y = 0.0;
    wo_output.momentum.z = 0.0;
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.torque.x = 0.0;
    wo_output.torque.y = 0.0;
    wo_output.torque.z = 0.0;
    return;
}

// Validate Configuration
if (wo_config.release_rad_s >= wo_config.warn_rad_s || 
    wo_config.warn_rad_s >= wo_config.trip_rad_s ||
    !isfinite(wo_config.dt_s) || wo_config.dt_s <= 0.0 ||
    !isfinite(wo_config.prediction_horizon_s) || wo_config.prediction_horizon_s < 0.0 ||
    !isfinite(wo_config.gain) || wo_config.gain < 0.0 ||
    !isfinite(wo_config.torque_limit) || wo_config.torque_limit <= 0.0 ||
    !isfinite(wo_config.torque_slew) || wo_config.torque_slew <= 0.0 ||
    wo_config.minimum_active_cycles < 1 || wo_config.minimum_active_cycles > 100 ||
    wo_config.release_cycles < 1 || wo_config.release_cycles > 100 ||
    wo_config.recovery_cycles < 1 || wo_config.recovery_cycles > 100) {

    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0;
    wo_output.elapsed = 0;
    wo_output.recovery_count = 0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (int i = 0; i < 4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum.x = 0.0;
    wo_output.momentum.y = 0.0;
    wo_output.momentum.z = 0.0;
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.torque.x = 0.0;
    wo_output.torque.y = 0.0;
    wo_output.torque.z = 0.0;
    return;
}

// Validate Wheels and Compute Momentum
if (wo_input.wheels == NULL || wo_input.count != 4) {
     if (wo_state.mode != WO_FAULT) {
         wo_state.mode = WO_FAULT;
     }
     wo_output.mode = WO_FAULT;
     wo_output.clean = 0;
     wo_output.elapsed = 0;
     wo_output.recovery_count = 0;
     wo_output.maximum_speed = 0.0;
     wo_output.predicted_maximum_speed = 0.0;
     for (int i = 0; i < 4; ++i) {
         wo_output.acceleration_rad_s2[i] = 0.0;
         wo_output.predicted_speed_rad_s[i] = 0.0;
     }
     wo_output.momentum.x = 0.0;
     wo_output.momentum.y = 0.0;
     wo_output.momentum.z = 0.0;
     wo_output.momentum_norm = 0.0;
     wo_output.predicted_trip_mask = 0U;
     wo_output.saturation_mask = 0U;
     wo_output.slew_mask = 0U;
     wo_output.torque.x = 0.0;
     wo_output.torque.y = 0.0;
     wo_output.torque.z = 0.0;
     return;
}

adcs_vec3_t momentum_sum = {0.0, 0.0, 0.0};
int wheels_valid = 1;
double max_abs_current = 0.0;
double max_abs_predicted = 0.0;
unint32 pred_trip_mask = 0U;

for (int i = 0; i < 4; ++i) {
    const adcs_wheel_t *w = &wo_input.wheels[i];
    if (!isfinite(w->speed_rad_s)) {
        wheels_valid = 0;
        break;
    }
    adcs_vec3_t axis_norm;
    if (adcs_vec3_normalize(&w->axis_body, ADCS_EPS_NORM, &axis_norm) != ADCS_OK) {
         wheels_valid = 0;
         break;
    }

    adcs_vec3_t term = adcs_vec3_scale(&axis_norm, w->inertia_kg_m2 * w->speed_rad_s);
    momentum_sum = adcs_vec3_add(&momentum_sum, &term);

    double abs_speed = fabs(w->speed_rad_s);
    if (abs_speed > max_abs_current) {
        max_abs_current = abs_speed;
    }
}

if (!wheels_valid) {
    if (wo_state.mode != WO_FAULT) {
        wo_state.mode = WO_FAULT;
    }
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0;
    wo_output.elapsed = 0;
    wo_output.recovery_count = 0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (int i = 0; i < 4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum.x = 0.0;
    wo_output.momentum.y = 0.0;
    wo_output.momentum.z = 0.0;
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.torque.x = 0.0;
    wo_output.torque.y = 0.0;
    wo_output.torque.z = 0.0;
    return;
}

wo_output.momentum = momentum_sum;
wo_output.momentum_norm = adcs_vec3_norm(&momentum_sum);

if (!isfinite(wo_output.momentum_norm)) {
    if (wo_state.mode != WO_FAULT) {
        wo_state.mode = WO_FAULT;
    }
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0;
    wo_output.elapsed = 0;
    wo_output.recovery_count = 0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (int i = 0; i < 4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum.x = 0.0;
    wo_output.momentum.y = 0.0;
    wo_output.momentum.z = 0.0;
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.torque.x = 0.0;
    wo_output.torque.y = 0.0;
    wo_output.torque.z = 0.0;
    return;
}

// 2. Acceleration Estimation and Prediction
double dt = wo_config.dt_s;
double horizon = wo_config.prediction_horizon_s;

for (int i = 0; i < 4; ++i) {
    double current_speed = wo_input.wheels[i].speed_rad_s;
    double accel = 0.0;
    double predicted_speed = current_speed;

    if (!wo_state.history_initialized) {
        wo_state.previous_speed_rad_s[i] = current_speed;
        wo_state.history_initialized = 1;
        accel = 0.0;
    } else {
        accel = (current_speed - wo_state.previous_speed_rad_s[i]) / dt;
        predicted_speed = current_speed + accel * horizon;
    }

    wo_output.acceleration_rad_s2[i] = accel;
    wo_output.predicted_speed_rad_s[i] = predicted_speed;

    double abs_pred = fabs(predicted_speed);
    if (abs_pred >= wo_config.trip_rad_s) {
        pred_trip_mask |= (unint32)(1U << i);
    }
    if (abs_pred > max_abs_predicted) {
        max_abs_predicted = abs_pred;
    }
}

for (int i = 0; i < 4; ++i) {
    wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
}

wo_output.maximum_speed = max_abs_current;
wo_output.predicted_maximum_speed = max_abs_predicted;
wo_output.predicted_trip_mask = pred_trip_mask;

// 3. State Machine Logic
wo_mode_t current_mode = wo_state.mode;
wo_mode_t next_mode = current_mode;
unint32 clean = wo_state.clean;
unint32 elapsed = wo_state.elapsed;
unint32 recovery_count = wo_state.recovery_count;

wo_output.saturation_mask = 0U;
wo_output.slew_mask = 0U;
wo_output.torque.x = 0.0;
wo_output.torque.y = 0.0;
wo_output.torque.z = 0.0;

switch (current_mode) {
    case WO_OFF:
        if (max_abs_predicted >= wo_config.warn_rad_s) {
            next_mode = WO_WATCH;
        }
        break;

    case WO_WATCH:
        if (max_abs_predicted >= wo_config.trip_rad_s) {
            next_mode = WO_ACTIVE;
            elapsed = 0;
        } else if (max_abs_predicted < wo_config.warn_rad_s) {
            next_mode = WO_OFF;
        }
        break;

    case WO_ACTIVE:
        elapsed++;
        if (elapsed >= wo_config.minimum_active_cycles) {
            if (max_abs_current <= wo_config.release_rad_s && 
                max_abs_predicted <= wo_config.release_rad_s) {
                clean++;
                if (clean >= wo_config.release_cycles) {
                    next_mode = WO_RECOVERY;
                    recovery_count = 0;
                }
            } else {
                clean = 0;
            }
        }

        adcs_vec3_t desired_torque = adcs_vec3_scale(&momentum_sum, -wo_config.gain);

        double tx = desired_torque.x;
        double ty = desired_torque.y;
        double tz = desired_torque.z;

        if (fabs(tx) > wo_config.torque_limit) {
            tx = copysign(wo_config.torque_limit, tx);
            wo_output.saturation_mask |= 1U;
        }
        if (fabs(ty) > wo_config.torque_limit) {
            ty = copysign(wo_config.torque_limit, ty);
            wo_output.saturation_mask |= 2U;
        }
        if (fabs(tz) > wo_config.torque_limit) {
            tz = copysign(wo_config.torque_limit, tz);
            wo_output.saturation_mask |= 4U;
        }

        adcs_vec3_t limited_torque = {tx, ty, tz};

        adcs_vec3_t delta = adcs_vec3_sub(&limited_torque, &wo_state.previous_torque);
        double delta_norm = adcs_vec3_norm(&delta);

        if (delta_norm > wo_config.torque_slew * dt) {
            double scale = (wo_config.torque_slew * dt) / delta_norm;
            adcs_vec3_t scaled_delta = adcs_vec3_scale(&delta, scale);
            adcs_vec3_t new_torque = adcs_vec3_add(&wo_state.previous_torque, &scaled_delta);

            if (delta_norm > 0.0) {
                 if (fabs(limited_torque.x) > FLT64_ZERO) wo_output.slew_mask |= 1U;
                 if (fabs(limited_torque.y) > FLT64_ZERO) wo_output.slew_mask |= 2U;
                 if (fabs(limited_torque.z) > FLT64_ZERO) wo_output.slew_mask |= 4U;
            }

            wo_output.torque = new_torque;
        } else {
            wo_output.torque = limited_torque;
        }

        wo_state.previous_torque = wo_output.torque;
        break;

    case WO_RECOVERY:
        adcs_vec3_t target_zero = {0.0, 0.0, 0.0};
        adcs_vec3_t delta_rec = adcs_vec3_sub(&target_zero, &wo_state.previous_torque);
        double delta_rec_norm = adcs_vec3_norm(&delta_rec);

        if (delta_rec_norm > wo_config.torque_slew * dt) {
            double scale = (wo_config.torque_slew * dt) / delta_rec_norm;
            adcs_vec3_t scaled_delta = adcs_vec3_scale(&delta_rec, scale);
            adcs_vec3_t new_torque_rec = adcs_vec3_add(&wo_state.previous_torque, &scaled_delta);

            if (delta_rec_norm > 0.0) {
                 if (fabs(wo_state.previous_torque.x) > FLT64_ZERO) wo_output.slew_mask |= 1U;
                 if (fabs(wo_state.previous_torque.y) > FLT64_ZERO) wo_output.slew_mask |= 2U;
                 if (fabs(wo_state.previous_torque.z) > FLT64_ZERO) wo_output.slew_mask |= 4U;
            }
            wo_output.torque = new_torque_rec;
        } else {
            wo_output.torque = target_zero;
        }

        wo_state.previous_torque = wo_output.torque;

        if (max_abs_predicted >= wo_config.trip_rad_s) {
            next_mode = WO_ACTIVE;
            elapsed = 0;
        } else {
            recovery_count++;
            if (recovery_count >= wo_config.recovery_cycles) {
                next_mode = WO_OFF;
            }
        }
        break;

    case WO_FAULT:
        next_mode = WO_FAULT;
        break;

    default:
        next_mode = WO_FAULT;
        break;
}

wo_state.mode = next_mode;
wo_state.clean = clean;
wo_state.elapsed = elapsed;
wo_state.recovery_count = recovery_count;

wo_output.mode = next_mode;
wo_output.clean = clean;
wo_output.elapsed = elapsed;
wo_output.recovery_count = recovery_count;

