        adcs_vec3_t scaled_slew = adcs_vec3_scale(&slew_delta, scale);
        final_torque = adcs_vec3_add(&wo_state.previous_torque, &scaled_slew);
        slew_mask = 7;
    } else {
        final_torque = mag_limited;
        slew_mask = 0;
    }

    wo_state.previous_torque = final_torque;
    sat_mask |= slew_mask; // Note: req says saturation_mask marks axis changed by mag limit, slew_mask by slew limit. They are separate outputs.
    // Correction: sat_mask should ONLY be from magnitude limit. slew_mask from slew limit.
    // My code above sets sat_mask correctly from loop. slew_mask separately.

} else {
    // OFF, WATCH, RECOVERY: Zero command
    adcs_vec3_t zero_cmd = (adcs_vec3_t){0,0,0};

    adcs_vec3_t slew_delta = adcs_vec3_sub(&zero_cmd, &wo_state.previous_torque);
    double delta_norm = adcs_vec3_norm(&slew_delta);

    if (delta_norm > wo_config.torque_slew) {
        double scale = wo_config.torque_slew / delta_norm;
        adcs_vec3_t scaled_slew_zero = adcs_vec3_scale(&slew_delta, scale);
        final_torque = adcs_vec3_add(&wo_state.previous_torque, &scaled_slew_zero);
        slew_mask = 7;
    } else {
        final_torque = zero_cmd;
        slew_mask = 0;
    }

    wo_state.previous_torque = final_torque;
}

wo_output.torque = final_torque;
wo_output.saturation_mask = sat_mask;
wo_output.slew_mask = slew_mask;
wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;
wo_output.recovery_count = wo_state.recovery_count;
